package vn.codex.garenapopup;
import android.accessibilityservice.AccessibilityService;import android.accessibilityservice.GestureDescription;import android.graphics.Path;import android.graphics.Rect;import android.content.*;import android.os.Bundle;import android.os.Handler;import android.os.Looper;import android.view.accessibility.AccessibilityEvent;import android.view.accessibility.AccessibilityNodeInfo;import android.view.accessibility.AccessibilityWindowInfo;import java.util.*;
public class GameLoginAccessibilityService extends AccessibilityService {
 private static final String GAME="com.garena.game.kgvn",ACTION="vn.codex.garenapopup.COMMAND";private boolean receiverReady;
 private final BroadcastReceiver commands=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){if("FILL_ACCOUNT".equals(i.getStringExtra("command")))processLogin();}};
 @Override protected void onServiceConnected(){super.onServiceConnected();if(!receiverReady){registerReceiver(commands,new IntentFilter(ACTION));receiverReady=true;}}
 @Override public void onAccessibilityEvent(AccessibilityEvent event){if(event==null||event.getPackageName()==null||!GAME.contentEquals(event.getPackageName()))return;processLogin();}
 private void processLogin(){
  android.content.SharedPreferences prefs=getSharedPreferences("login",MODE_PRIVATE);
  if(!prefs.getBoolean("fillPending",false))return;
  AccessibilityNodeInfo root=findGameRoot();if(root==null){prefs.edit().putString("state","Mở Liên Quân để tiếp tục").apply();return;}
  String screen=collectText(root).toLowerCase(Locale.ROOT);
  if(screen.matches("(?s).*(captcha|otp|verification|verify|mã xác minh|mã bảo mật|xác minh|xác thực).*")){prefs.edit().putBoolean("fillPending",false).putString("state","Màn hình xác minh; app dừng để bạn xử lý").apply();return;}
  ArrayList<AccessibilityNodeInfo> fields=new ArrayList<>();collectEditable(root,fields);AccessibilityNodeInfo user=null,pass=null;
  for(AccessibilityNodeInfo n:fields){if(n.isPassword())pass=n;else if(user==null)user=n;}
  if(user==null||pass==null){prefs.edit().putString("state","Mở form Garena thủ công rồi chọn acc").apply();return;}  String username=prefs.getString("user",""),password=prefs.getString("pass","");if(username.isEmpty()||password.isEmpty())return;
  if(!setText(user,username)||!setText(pass,password)){prefs.edit().putBoolean("fillPending",false).putString("state","Không điền được form đăng nhập").apply();return;}
  boolean autoSubmit=prefs.getBoolean("autoSubmit",true);if(!autoSubmit){prefs.edit().putBoolean("fillPending",false).putInt("loginStage",2).putString("state","Đã điền; chờ bạn đăng nhập").apply();return;}long delay=1500;try{delay=Math.max(500,Math.min(4000,Math.round(Float.parseFloat(prefs.getString("operationDelay","1.5"))*1000)));}catch(Exception ignored){}prefs.edit().putBoolean("fillPending",false).putInt("loginStage",2).putString("state","Đã điền; chờ "+delay+" ms trước khi đăng nhập").apply();
  new Handler(Looper.getMainLooper()).postDelayed(()->{AccessibilityNodeInfo latest=findGameRoot();AccessibilityNodeInfo submit=latest==null?null:findSubmitButton(latest);if(submit==null){prefs.edit().putString("state","Đã điền; không thấy nút Đăng Nhập Ngay").apply();return;}tapNode(submit,"Đã điền; đang chạm Đăng Nhập Ngay","Đã chạm nút Đăng Nhập Ngay");},delay);
 }
 private void tapNode(AccessibilityNodeInfo node,String pending,String done){Rect b=new Rect();node.getBoundsInScreen(b);if(b.isEmpty()){getSharedPreferences("login",MODE_PRIVATE).edit().putString("state","Không xác định được vị trí nút; hãy chạm thủ công").apply();return;}Path p=new Path();p.moveTo(b.exactCenterX(),b.exactCenterY());GestureDescription g=new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(p,0,80)).build();boolean sent=dispatchGesture(g,new GestureResultCallback(){@Override public void onCompleted(GestureDescription gesture){getSharedPreferences("login",MODE_PRIVATE).edit().putString("state",done).apply();}@Override public void onCancelled(GestureDescription gesture){getSharedPreferences("login",MODE_PRIVATE).edit().putString("state","Thao tác chạm bị hủy; hãy chạm thủ công").apply();}},null);if(!sent)getSharedPreferences("login",MODE_PRIVATE).edit().putString("state","Không gửi được thao tác chạm; hãy chạm thủ công").apply();else getSharedPreferences("login",MODE_PRIVATE).edit().putString("state",pending).apply();} private AccessibilityNodeInfo findGameRoot(){AccessibilityNodeInfo root=getRootInActiveWindow();if(root!=null&&GAME.contentEquals(root.getPackageName()))return root;try{for(AccessibilityWindowInfo w:getWindows()){AccessibilityNodeInfo r=w.getRoot();if(r!=null&&GAME.contentEquals(r.getPackageName()))return r;}}catch(Exception ignored){}return null;}
 private AccessibilityNodeInfo findSubmitButton(AccessibilityNodeInfo n){if(n.isClickable()){String s=nodeText(n);if(s.equals("đăng nhập")||s.equals("login")||s.equals("đăng nhập ngay"))return n;}for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo c=n.getChild(i);if(c!=null){AccessibilityNodeInfo found=findSubmitButton(c);if(found!=null)return found;}}return null;}
 private String nodeText(AccessibilityNodeInfo n){CharSequence t=n.getText(),d=n.getContentDescription();return ((t==null?"":t)+" "+(d==null?"":d)).trim().toLowerCase(Locale.ROOT);}
 private boolean setText(AccessibilityNodeInfo n,String value){Bundle b=new Bundle();b.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,value);return n.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,b);}
 private void collectEditable(AccessibilityNodeInfo n,List<AccessibilityNodeInfo> out){if(n.isVisibleToUser()&&n.isEditable()&&n.isEnabled())out.add(n);for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo c=n.getChild(i);if(c!=null)collectEditable(c,out);}}
 private String collectText(AccessibilityNodeInfo n){StringBuilder s=new StringBuilder();CharSequence t=n.getText(),d=n.getContentDescription();if(t!=null)s.append(t).append(' ');if(d!=null)s.append(d).append(' ');for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo c=n.getChild(i);if(c!=null)s.append(collectText(c));}return s.toString();}
 @Override public void onInterrupt(){}@Override public void onDestroy(){if(receiverReady)unregisterReceiver(commands);super.onDestroy();}
}
